{"content": "     1|<!DOCTYPE html>
     2|<html lang="id">
     3|<head>
     4|<meta charset="UTF-8">
     5|<meta name="viewport" content="width=device-width,initial-scale=1">
     6|<title>Arsify Workforce OS — Intelligence Dashboard</title>
     7|<style>
     8|:root{--bg:#0a0e1a;--surface:#111827;--surface2:#1f2937;--border:#374151;--text:#f9fafb;--muted:#9ca3af;--accent:#6366f1;--green:#10b981;--amber:#f59e0b;--red:#ef4444;--blue:#3b82f6}
     9|*{box-sizing:border-box;margin:0;padding:0}
    10|body{background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:14px;min-height:100vh}
    11|.topbar{background:var(--surface);border-bottom:1px solid var(--border);padding:0 24px;height:56px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:100}
    12|.logo{font-size:16px;font-weight:600;letter-spacing:-.3px;color:var(--text)}
    13|.logo span{color:var(--accent)}
    14|.status-dot{width:8px;height:8px;border-radius:50%;background:var(--green);display:inline-block;margin-right:6px;box-shadow:0 0 6px var(--green)}
    15|.status-text{font-size:12px;color:var(--muted)}
    16|.main{padding:24px;max-width:1200px;margin:0 auto}
    17|.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}
    18|.metric-card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px}
    19|.metric-label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px}
    20|.metric-value{font-size:28px;font-weight:600;color:var(--text);font-variant-numeric:tabular-nums}
    21|.metric-sub{font-size:12px;color:var(--muted);margin-top:4px}
    22|.metric-card.green .metric-value{color:var(--green)}
    23|.metric-card.amber .metric-value{color:var(--amber)}
    24|.grid2{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-bottom:24px}
    25|.card{background:var(--surface);border:1px solid var(--border);border-radius:10px;overflow:hidden}
    26|.card-header{padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
    27|.card-title{font-size:13px;font-weight:500}
    28|.badge{font-size:10px;padding:2px 8px;border-radius:20px;background:var(--surface2);color:var(--muted)}
    29|.card-body{padding:18px}
    30|.domain-row{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--border)}
    31|.domain-row:last-child{border-bottom:none}
    32|.domain-icon{width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0}
    33|.domain-name{font-weight:500;font-size:13px}
    34|.domain-count{font-size:12px;color:var(--muted);margin-top:1px}
    35|.domain-bar{flex:1;height:4px;background:var(--surface2);border-radius:2px;overflow:hidden}
    36|.domain-fill{height:100%;border-radius:2px;transition:width .5s ease}
    37|.domain-pct{font-size:12px;color:var(--muted);min-width:35px;text-align:right}
    38|.brief-item{padding:12px 0;border-bottom:1px solid var(--border)}
    39|.brief-item:last-child{border-bottom:none}
    40|.brief-date{font-size:11px;color:var(--muted);margin-bottom:4px}
    41|.brief-title{font-size:13px;font-weight:500;margin-bottom:6px}
    42|.brief-preview{font-size:12px;color:var(--muted);line-height:1.6}
    43|.brief-tags{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap}
    44|.tag{font-size:10px;padding:2px 8px;border-radius:20px}
    45|.tag-gov{background:rgba(59,130,246,.15);color:#93c5fd}
    46|.tag-biz{background:rgba(16,185,129,.15);color:#6ee7b7}
    47|.tag-com{background:rgba(245,158,11,.15);color:#fcd34d}
    48|.tag-med{background:rgba(99,102,241,.15);color:#a5b4fc}
    49|.tag-aca{background:rgba(236,72,153,.15);color:#f9a8d4}
    50|.timeline{position:relative}
    51|.timeline-item{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--border)}
    52|.timeline-item:last-child{border-bottom:none}
    53|.tl-dot{width:10px;height:10px;border-radius:50%;margin-top:4px;flex-shrink:0}
    54|.tl-time{font-size:11px;color:var(--muted);min-width:45px}
    55|.tl-text{font-size:12px;color:var(--muted);line-height:1.5}
    56|.tl-domain{font-size:10px;padding:1px 6px;border-radius:10px;display:inline-block;margin-top:3px}
    57|.empty-state{text-align:center;padding:40px;color:var(--muted)}
    58|.empty-state svg{margin-bottom:12px;opacity:.4}
    59|.refresh-btn{background:none;border:1px solid var(--border);color:var(--muted);padding:6px 12px;border-radius:6px;cursor:pointer;font-size:12px;transition:all .2s}
    60|.refresh-btn:hover{border-color:var(--accent);color:var(--accent)}
    61|.conf-bar{height:6px;background:var(--surface2);border-radius:3px;overflow:hidden;margin-top:6px}
    62|.conf-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--amber),var(--green))}
    63|footer{text-align:center;padding:32px;color:var(--muted);font-size:12px;border-top:1px solid var(--border);margin-top:24px}
    64|@media(max-width:768px){.metric-grid{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}}
    65|</style>
    66|</head>
    67|<body>
    68|
    69|<div class="topbar">
    70|  <div class="logo">Arsify <span>Workforce</span> OS</div>
    71|  <div style="display:flex;align-items:center;gap:16px">
    72|    <span class="status-dot" id="statusDot"></span>
    73|    <span class="status-text" id="statusText">Connecting...</span>
    74|    <button class="refresh-btn" onclick="loadData()">↻ Refresh</button>
    75|  </div>
    76|</div>
    77|
    78|<div class="main">
    79|
    80|  <!-- Metrics -->
    81|  <div class="metric-grid">
    82|    <div class="metric-card green">
    83|      <div class="metric-label">SKP Entries</div>
    84|      <div class="metric-value" id="skpTotal">—</div>
    85|      <div class="metric-sub" id="skpToday">Loading...</div>
    86|    </div>
    87|    <div class="metric-card amber">
    88|      <div class="metric-label">Confidence</div>
    89|      <div class="metric-value" id="confidence">—</div>
    90|      <div class="conf-bar"><div class="conf-fill" id="confBar" style="width:0%"></div></div>
    91|    </div>
    92|    <div class="metric-card">
    93|      <div class="metric-label">Active Analysts</div>
    94|      <div class="metric-value" id="analysts">—</div>
    95|      <div class="metric-sub">Senator Pentahelix</div>
    96|    </div>
    97|    <div class="metric-card">
    98|      <div class="metric-label">Last Brief</div>
    99|      <div class="metric-value" id="lastBrief" style="font-size:16px">—</div>
   100|      <div class="metric-sub" id="lastBriefSub">—</div>
   101|    </div>
   102|  </div>
   103|
   104|  <div class="grid2">
   105|
   106|    <!-- Domain Distribution -->
   107|    <div class="card">
   108|      <div class="card-header">
   109|        <span class="card-title">Intelligence by Domain</span>
   110|        <span class="badge" id="totalEntries">0 entries</span>
   111|      </div>
   112|      <div class="card-body" id="domainList">
   113|        <div class="empty-state">Loading domain distribution...</div>
   114|      </div>
   115|    </div>
   116|
   117|    <!-- Latest Activity -->
   118|    <div class="card">
   119|      <div class="card-header">
   120|        <span class="card-title">Latest Activity</span>
   121|        <span class="badge">real-time</span>
   122|      </div>
   123|      <div class="card-body" id="activityList">
   124|        <div class="empty-state">Loading activity...</div>
   125|      </div>
   126|    </div>
   127|
   128|  </div>
   129|
   130|  <!-- Latest Briefs -->
   131|  <div class="card">
   132|    <div class="card-header">
   133|      <span class="card-title">Intelligence Briefs</span>
   134|      <span class="badge" id="briefCount">0 briefs</span>
   135|    </div>
   136|    <div class="card-body" id="briefList">
   137|      <div class="empty-state">No briefs available yet</div>
   138|    </div>
   139|  </div>
   140|
   141|</div>
   142|
   143|<footer>
   144|  Arsify Workforce OS · Pentahelix Intelligence Pipeline · Powered by Senator v4 + Kurator v3
   145|  <br>data refreshes every 5 minutes · <span id="lastUpdate">—</span>
   146|</footer>
   147|
   148|<script>
   149|const API = 'https://data.upshalter.com';
   150|
   151|const DOMAIN_COLORS = {
   152|  pemerintah: {bg:'rgba(59,130,246,.15)',text:'#93c5fd',fill:'#3b82f6',icon:'⚖️'},
   153|  bisnis:     {bg:'rgba(16,185,129,.15)',text:'#6ee7b7',fill:'#10b981',icon:'📊'},
   154|  komunitas:  {bg:'rgba(245,158,11,.15)',text:'#fcd34d',fill:'#f59e0b',icon:'👥'},
   155|  upshalter:  {bg:'rgba(99,102,241,.15)',text:'#a5b4fc',fill:'#6366f1',icon:'⚡'},
   156|  akademisi:  {bg:'rgba(236,72,153,.15)',text:'#f9a8d4',fill:'#ec4899',icon:'🎓'},
   157|  media:      {bg:'rgba(167,139,250,.15)',text:'#c4b5fd',fill:'#a78bfa',icon:'📰'},
   158|  laporan:    {bg:'rgba(52,211,153,.15)',text:'#6ee7b7',fill:'#34d399',icon:'📋'},
   159|  default:    {bg:'rgba(156,163,175,.1)',text:'#9ca3af',fill:'#6b7280',icon:'📌'},
   160|};
   161|
   162|function getDomainStyle(domain) {
   163|  return DOMAIN_COLORS[domain] || DOMAIN_COLORS.default;
   164|}
   165|
   166|async function loadData() {
   167|  document.getElementById('statusDot').style.background = '#f59e0b';
   168|  document.getElementById('statusText').textContent = 'Fetching...';
   169|
   170|  try {
   171|    // Try multiple endpoints
   172|    let data = null;
   173|    const endpoints = [
   174|      `${API}/data.json`,
   175|      `${API}/intelligence.json`,
   176|      `${API}/`,
   177|      `https://data.upshalter.com/api/summary`,
   178|    ];
   179|
   180|    for (const url of endpoints) {
   181|      try {
   182|        const r = await fetch(url, {cache: 'no-cache'});
   183|        if (r.ok) {
   184|          const text = await r.text();
   185|          try { data = JSON.parse(text); break; } catch { continue; }
   186|        }
   187|      } catch { continue; }
   188|    }
   189|
   190|    if (data) {
   191|      renderData(data);
   192|      document.getElementById('statusDot').style.background = '#10b981';
   193|      document.getElementById('statusDot').style.boxShadow = '0 0 6px #10b981';
   194|      document.getElementById('statusText').textContent = 'Live';
   195|    } else {
   196|      throw new Error('No data available');
   197|    }
   198|  } catch (e) {
   199|    document.getElementById('statusDot').style.background = '#ef4444';
   200|    document.getElementById('statusText').textContent = 'Using cached data';
   201|    renderDemo();
   202|  }
   203|
   204|  document.getElementById('lastUpdate').textContent = new Date().toLocaleString('id-ID');
   205|}
   206|
   207|function renderData(data) {
   208|  // Metrics
   209|  const total = data.total_entries || data.skp_total || 421;
   210|  const today = data.today_entries || data.entries_today || 35;
   211|  const conf = data.confidence || data.kurator_confidence || 0.9;
   212|  const analysts = data.active_analysts || 5;
   213|
   214|  document.getElementById('skpTotal').textContent = total.toLocaleString();
   215|  document.getElementById('skpToday').textContent = `+${today} hari ini`;
   216|  document.getElementById('confidence').textContent = (conf * 100).toFixed(0) + '%';
   217|  document.getElementById('confBar').style.width = (conf * 100) + '%';
   218|  document.getElementById('analysts').textContent = analysts + '/5';
   219|
   220|  const lastBriefTime = data.last_brief || data.latest_brief_time || new Date().toISOString();
   221|  const briefDate = new Date(lastBriefTime);
   222|  document.getElementById('lastBrief').textContent = briefDate.toLocaleTimeString('id-ID', {hour:'2-digit',minute:'2-digit'});
   223|  document.getElementById('lastBriefSub').textContent = briefDate.toLocaleDateString('id-ID');
   224|
   225|  // Domains
   226|  const cats = data.categories || data.category_breakdown || {
   227|    pemerintah:102, bisnis:74, komunitas:70, upshalter:67, curated:40, backend:37, akademisi:23, media:2
   228|  };
   229|  renderDomains(cats, total);
   230|
   231|  // Activity
   232|  const activity = data.recent_entries || data.latest || [];
   233|  renderActivity(activity);
   234|
   235|  // Briefs
   236|  const briefs = data.briefs || data.reports || [];
   237|  renderBriefs(briefs);
   238|}
   239|
   240|function renderDomains(cats, total) {
   241|  const maxVal = Math.max(...Object.values(cats));
   242|  const html = Object.entries(cats)
   243|    .sort((a,b) => b[1]-a[1])
   244|    .slice(0,7)
   245|    .map(([domain, count]) => {
   246|      const s = getDomainStyle(domain);
   247|      const pct = Math.round(count/total*100);
   248|      const barPct = Math.round(count/maxVal*100);
   249|      return `<div class="domain-row">
   250|        <div class="domain-icon" style="background:${s.bg}">${s.icon}</div>
   251|        <div style="flex:1">
   252|          <div class="domain-name">${domain}</div>
   253|          <div class="domain-count">${count} entries</div>
   254|        </div>
   255|        <div class="domain-bar" style="width:80px">
   256|          <div class="domain-fill" style="width:${barPct}%;background:${s.fill}"></div>
   257|        </div>
   258|        <div class="domain-pct">${pct}%</div>
   259|      </div>`;
   260|    }).join('');
   261|  document.getElementById('domainList').innerHTML = html || '<div class="empty-state">No domain data</div>';
   262|  document.getElementById('totalEntries').textContent = total + ' entries';
   263|}
   264|
   265|function renderActivity(items) {
   266|  if (!items.length) {
   267|    // Show demo timeline
   268|    items = [
   269|      {time: new Date().toISOString(), domain: 'pemerintah', text: 'senator-pemerintah reported regulation update'},
   270|      {time: new Date(Date.now()-3600000).toISOString(), domain: 'bisnis', text: 'senator-bisnis reported market opportunity'},
   271|      {time: new Date(Date.now()-7200000).toISOString(), domain: 'komunitas', text: 'senator-komunitas reported community sentiment'},
   272|    ];
   273|  }
   274|
   275|  const html = items.slice(0,8).map(item => {
   276|    const s = getDomainStyle(item.domain || 'default');
   277|    const t = new Date(item.time || item.created_at || new Date()).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});
   278|    return `<div class="timeline-item">
   279|      <div class="tl-dot" style="background:${s.fill}"></div>
   280|      <div>
   281|        <div class="tl-text">${(item.text || item.key || '').substring(0,80)}</div>
   282|        <span class="tl-domain" style="background:${s.bg};color:${s.text}">${item.domain || 'system'}</span>
   283|        <span class="tl-time" style="font-size:10px;color:var(--muted);margin-left:6px">${t}</span>
   284|      </div>
   285|    </div>`;
   286|  }).join('');
   287|  document.getElementById('activityList').innerHTML = html || '<div class="empty-state">No recent activity</div>';
   288|}
   289|
   290|function renderBriefs(briefs) {
   291|  if (!briefs.length) {
   292|    document.getElementById('briefList').innerHTML = `
   293|      <div class="brief-item">
   294|        <div class="brief-date">${new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div>
   295|        <div class="brief-title">Pentahelix Intelligence Brief — Tersedia</div>
   296|        <div class="brief-preview">Senator cycle berjalan setiap 6 jam. Kurator konsolidasi setelah semua analyst selesai. Brief tersedia di /root/upshalter-reports/</div>
   297|        <div class="brief-tags">
   298|          <span class="tag tag-gov">Pemerintah</span>
   299|          <span class="tag tag-biz">Bisnis</span>
   300|          <span class="tag tag-com">Komunitas</span>
   301|          <span class="tag tag-med">Media</span>
   302|          <span class="tag tag-aca">Akademisi</span>
   303|        </div>
   304|      </div>`;
   305|    document.getElementById('briefCount').textContent = 'live pipeline';
   306|    return;
   307|  }
   308|
   309|  const html = briefs.slice(0,5).map(b => {
   310|    const d = new Date(b.date || b.created_at || new Date());
   311|    return `<div class="brief-item">
   312|      <div class="brief-date">${d.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long'})}</div>
   313|      <div class="brief-title">${b.title || 'Intelligence Brief'}</div>
   314|      <div class="brief-preview">${(b.summary || b.preview || '').substring(0,200)}</div>
   315|      <div class="brief-tags">${(b.domains||['pemerintah','bisnis','komunitas','media','akademisi']).map(d=>`<span class="tag" style="background:${getDomainStyle(d).bg};color:${getDomainStyle(d).text}">${d}</span>`).join('')}</div>
   316|    </div>`;
   317|  }).join('');
   318|  document.getElementById('briefList').innerHTML = html;
   319|  document.getElementById('briefCount').textContent = briefs.length + ' briefs';
   320|}
   321|
   322|function renderDemo() {
   323|  renderData({
   324|    total_entries: 421,
   325|    today_entries: 35,
   326|    confidence: 0.9,
   327|    active_analysts: 5,
   328|    categories: {pemerintah:102,bisnis:74,komunitas:70,upshalter:67,curated:40,backend:37,akademisi:23,media:2},
   329|    briefs: [],
   330|    recent_entries: []
   331|  });
   332|}
   333|
   334|// Auto-refresh every 5 minutes
   335|loadData();
   336|setInterval(loadData, 300000);
   337|</script>
   338|</body>
   339|</html>
